// Package aetherixstorage is a Caddy storage module (caddy.storage.aetherix)
// that keeps certificates and ACME locks in the AetherixCloud replicated
// store. It speaks the small HTTP protocol served by aetherixd
// (internal/ingress.StorageHandler) on the node's loopback mesh API, so every
// ingress node shares one set of certificates and one ACME lock namespace.
//
// JSON config (generated by aetherixd, you normally never write it):
//
//	"storage": {"module": "aetherix", "endpoint": "http://127.0.0.1:8080/internal/ingress/storage/", "token": "..."}
package aetherixstorage

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/certmagic"
)

func init() { caddy.RegisterModule(&Storage{}) }

// Storage implements certmagic.Storage over the aetherixd HTTP protocol.
type Storage struct {
	Endpoint string `json:"endpoint"`
	Token    string `json:"token"`

	once   sync.Once
	client *http.Client

	mu    sync.Mutex
	locks map[string]*heldLock
}

type heldLock struct {
	owner string
	stop  chan struct{}
}

// CaddyModule implements caddy.Module.
func (*Storage) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{ID: "caddy.storage.aetherix", New: func() caddy.Module { return new(Storage) }}
}

// CertMagicStorage implements caddy.StorageConverter.
func (s *Storage) CertMagicStorage() (certmagic.Storage, error) {
	if s.Endpoint == "" || s.Token == "" {
		return nil, errors.New("aetherix storage: endpoint and token are required")
	}
	s.once.Do(func() {
		s.client = &http.Client{Timeout: 30 * time.Second}
		s.locks = map[string]*heldLock{}
		s.Endpoint = strings.TrimRight(s.Endpoint, "/") + "/"
	})
	return s, nil
}

var (
	_ caddy.StorageConverter = (*Storage)(nil)
	_ certmagic.Storage      = (*Storage)(nil)
)

type request struct {
	Key       string `json:"key,omitempty"`
	Value     []byte `json:"value,omitempty"`
	Prefix    string `json:"prefix,omitempty"`
	Recursive bool   `json:"recursive,omitempty"`
	Name      string `json:"name,omitempty"`
	Owner     string `json:"owner,omitempty"`
}

// call performs one protocol operation. out may be nil.
func (s *Storage) call(ctx context.Context, op string, in request, out any) (int, error) {
	body, _ := json.Marshal(in)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.Endpoint+op, bytes.NewReader(body))
	if err != nil {
		return 0, err
	}
	req.Header.Set("Authorization", "Bearer "+s.Token)
	req.Header.Set("Content-Type", "application/json")
	resp, err := s.client.Do(req)
	if err != nil {
		return 0, err
	}
	defer resp.Body.Close()
	switch {
	case resp.StatusCode == http.StatusNotFound:
		return resp.StatusCode, fs.ErrNotExist
	case resp.StatusCode == http.StatusConflict:
		return resp.StatusCode, nil
	case resp.StatusCode/100 != 2:
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 2048))
		return resp.StatusCode, fmt.Errorf("aetherix storage %s: %s: %s", op, resp.Status, strings.TrimSpace(string(b)))
	}
	if out != nil {
		return resp.StatusCode, json.NewDecoder(resp.Body).Decode(out)
	}
	return resp.StatusCode, nil
}

func (s *Storage) Store(ctx context.Context, key string, value []byte) error {
	_, err := s.call(ctx, "store", request{Key: key, Value: value}, nil)
	return err
}

func (s *Storage) Load(ctx context.Context, key string) ([]byte, error) {
	var out struct {
		Value []byte `json:"value"`
	}
	if _, err := s.call(ctx, "load", request{Key: key}, &out); err != nil {
		return nil, err
	}
	return out.Value, nil
}

func (s *Storage) Delete(ctx context.Context, key string) error {
	_, err := s.call(ctx, "delete", request{Key: key}, nil)
	return err
}

func (s *Storage) Exists(ctx context.Context, key string) bool {
	var out struct {
		Exists bool `json:"exists"`
	}
	_, err := s.call(ctx, "exists", request{Key: key}, &out)
	return err == nil && out.Exists
}

func (s *Storage) List(ctx context.Context, path string, recursive bool) ([]string, error) {
	var out struct {
		Keys []string `json:"keys"`
	}
	if _, err := s.call(ctx, "list", request{Prefix: path, Recursive: recursive}, &out); err != nil {
		return nil, err
	}
	return out.Keys, nil
}

func (s *Storage) Stat(ctx context.Context, key string) (certmagic.KeyInfo, error) {
	var out struct {
		Key        string    `json:"key"`
		Modified   time.Time `json:"modified"`
		Size       int64     `json:"size"`
		IsTerminal bool      `json:"is_terminal"`
	}
	if _, err := s.call(ctx, "stat", request{Key: key}, &out); err != nil {
		return certmagic.KeyInfo{}, err
	}
	return certmagic.KeyInfo{Key: out.Key, Modified: out.Modified, Size: out.Size, IsTerminal: out.IsTerminal}, nil
}

// Lock blocks until the cluster-wide lock is acquired. The daemon-side lease
// expires after a few minutes, so a heartbeat renews it until Unlock.
func (s *Storage) Lock(ctx context.Context, name string) error {
	var b [8]byte
	_, _ = rand.Read(b[:])
	owner := hex.EncodeToString(b[:])
	for {
		code, err := s.call(ctx, "lock", request{Name: name, Owner: owner}, nil)
		if err == nil && code == http.StatusOK {
			break
		}
		if err != nil && !errors.Is(err, context.DeadlineExceeded) && ctx.Err() != nil {
			return err
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(time.Second):
		}
	}
	h := &heldLock{owner: owner, stop: make(chan struct{})}
	s.mu.Lock()
	s.locks[name] = h
	s.mu.Unlock()
	go func() {
		t := time.NewTicker(time.Minute)
		defer t.Stop()
		for {
			select {
			case <-h.stop:
				return
			case <-t.C:
				rctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
				_, _ = s.call(rctx, "lock", request{Name: name, Owner: owner}, nil)
				cancel()
			}
		}
	}()
	return nil
}

func (s *Storage) Unlock(ctx context.Context, name string) error {
	s.mu.Lock()
	h := s.locks[name]
	delete(s.locks, name)
	s.mu.Unlock()
	if h == nil {
		return nil
	}
	close(h.stop)
	_, err := s.call(ctx, "unlock", request{Name: name, Owner: h.owner}, nil)
	return err
}
